CREATE TABLE IF NOT EXISTS continuity_drill_data(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,drill_id TEXT NOT NULL,record_key TEXT NOT NULL,payload_json TEXT NOT NULL,checksum TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,property_id,drill_id,record_key));
CREATE TABLE IF NOT EXISTS continuity_drill_runs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,status TEXT NOT NULL,rpo_target_seconds INTEGER NOT NULL,rto_target_seconds INTEGER NOT NULL,rpo_actual_seconds REAL NOT NULL,rto_actual_seconds REAL NOT NULL,backup_record_count INTEGER NOT NULL,restored_record_count INTEGER NOT NULL,integrity_verified INTEGER NOT NULL,outage_evidence_json TEXT NOT NULL,privileged_alert_id TEXT,executed_by TEXT NOT NULL,executed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS privileged_change_alerts(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,event_type TEXT NOT NULL,severity TEXT NOT NULL,actor TEXT NOT NULL,setting_key TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,alert_status TEXT NOT NULL,previous_hash TEXT NOT NULL,checksum TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,property_id,checksum));
CREATE INDEX IF NOT EXISTS continuity_drill_scope_idx ON continuity_drill_runs(organization_id,property_id,executed_at);
CREATE INDEX IF NOT EXISTS continuity_data_scope_idx ON continuity_drill_data(organization_id,property_id,drill_id,record_key);
CREATE INDEX IF NOT EXISTS privileged_alert_scope_idx ON privileged_change_alerts(organization_id,property_id,created_at);
